const pages = await browser.pages.list();
const ga = pages.filter(x => (x.url || '').includes('analytics.google.com'));
if (!ga.length) { console.log('no hay pestana de GA4'); return 'no'; }
const p = await browser.page(ga[ga.length - 1].pageId);
const links = await p.evaluate(() => { try { return Array.from(document.querySelectorAll('a[href*="reports"]')).map(a => ({ t: String(a.innerText || a.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim().slice(0, 40), h: a.getAttribute('href') })).filter(x => x.t).slice(0, 30); } catch (e) { return [] } });
console.log('SIDEBAR ' + JSON.stringify(links));
return 'ok';
